import { useEffect, useRef, useState } from 'react';
import { Link, useSearchParams } from 'react-router-dom';
import { auth as authApi } from '@/api/endpoints.js';
import { isApiError } from '@/api/errors.js';
import { Icon } from '@/components/ui/Icon.js';
import { t } from '@/i18n/index.js';
import { settingsPath } from '@/features/settings/paths.js';
import { useAuth } from './session.js';
import styles from './SignIn.module.css';

type Outcome = 'working' | 'done' | 'invalid' | 'offline';

/**
 * Where the unsubscribe link at the bottom of a news e-mail lands. It asks
 * for nothing: no session, no password, no confirmation. Somebody who has
 * lost their password must still be able to stop the e-mails, so the token
 * in the link is the whole of it, and following the same link twice says the
 * same thing rather than complaining.
 *
 * Only product news stops. A confirmation or a password reset still arrives,
 * because those are not news; the copy says so, so nobody thinks they have
 * broken their account.
 */
export function Unsubscribe(): React.JSX.Element {
  const [params] = useSearchParams();
  const token = params.get('token') ?? '';
  const [outcome, setOutcome] = useState<Outcome>(token === '' ? 'invalid' : 'working');
  const started = useRef(false);
  const status = useAuth((state) => state.status);

  useEffect(() => {
    if (started.current || token === '') return;
    started.current = true;
    authApi
      .unsubscribe(token)
      .then(() => {
        setOutcome('done');
      })
      .catch((error: unknown) => {
        setOutcome(isApiError(error, 'offline') ? 'offline' : 'invalid');
      });
  }, [token]);

  return (
    <main className={styles.wrap}>
      <div className={styles.brand}>
        <div className={styles.mark}>
          <Icon name="notebook" size={22} weight={2} />
        </div>
        <h1 className={styles.name}>{t('app.name')}</h1>
      </div>
      <div className={styles.form}>
        <div className={styles.formTitle}>
          {outcome === 'done'
            ? t('unsubscribe.doneTitle')
            : outcome === 'invalid'
              ? t('unsubscribe.failedTitle')
              : t('unsubscribe.title')}
        </div>
        {outcome === 'working' && <p className={styles.lead}>{t('state.loading')}</p>}
        {outcome === 'done' && (
          <>
            <p className={styles.success} role="status">
              {t('unsubscribe.done')}
            </p>
            <Link to={status === 'ready' ? '/' : '/auth'} className={styles.submit}>
              {t('unsubscribe.continue')}
            </Link>
          </>
        )}
        {outcome === 'invalid' && (
          <>
            <p className={styles.error} role="alert">
              {t('unsubscribe.invalid')}
            </p>
            <Link
              to={status === 'ready' ? settingsPath('notifications') : '/auth'}
              className={styles.textLink}
            >
              {status === 'ready' ? t('unsubscribe.continue') : t('auth.backToSignIn')}
            </Link>
          </>
        )}
        {outcome === 'offline' && (
          <p className={styles.error} role="alert">
            {t('error.offline')}
          </p>
        )}
      </div>
    </main>
  );
}
