import { useEffect, useState } from 'react';

/** Whether two instants fall on the same day on this device's clock. */
function sameLocalDay(a: Date, b: Date): boolean {
  return a.getFullYear() === b.getFullYear() && a.getMonth() === b.getMonth() && a.getDate() === b.getDate();
}

/** Milliseconds from `now` to the next local midnight. */
function untilMidnight(now: Date): number {
  const midnight = new Date(now);
  midnight.setHours(24, 0, 0, 0);
  return midnight.getTime() - now.getTime();
}

/**
 * The moment a screen counts "today" from, renewed when the local day turns
 * over. A screen that took `new Date()` once kept yesterday's due counts in a
 * tab or an installed app left open past midnight. A timer handles a screen
 * that is watched at midnight; a sleeping device or a throttled background
 * tab may miss it, so coming back into view checks the day again.
 */
export function useCurrentDay(): Date {
  const [now, setNow] = useState(() => new Date());

  useEffect(() => {
    let timer: number | undefined;
    const renew = (): void => {
      const fresh = new Date();
      if (sameLocalDay(now, fresh)) arm(fresh);
      else setNow(fresh);
    };
    // A timer can fire a moment early; then it is simply armed again.
    const arm = (from: Date): void => {
      window.clearTimeout(timer);
      timer = window.setTimeout(renew, untilMidnight(from));
    };
    arm(now);
    const onVisible = (): void => {
      if (document.visibilityState === 'visible') renew();
    };
    document.addEventListener('visibilitychange', onVisible);
    return () => {
      window.clearTimeout(timer);
      document.removeEventListener('visibilitychange', onVisible);
    };
  }, [now]);

  return now;
}
