/**
 * The OAuth state parameter: a nonce this browser minted when it started the
 * redirect, checked when Google returns. Without it a link crafted by someone
 * else could sign this browser into their account. It lives in sessionStorage
 * because it must survive the round trip and nothing else; it is not data.
 */
const KEY = 'lexpad.oauth.state';

export function issueOAuthState(): string {
  const state = crypto.randomUUID();
  try {
    sessionStorage.setItem(KEY, state);
  } catch {
    // Storage blocked: the callback will refuse, and the user sees sign-in again.
  }
  return state;
}

/** Consumes the stored nonce and reports whether the returned one matches it. */
export function consumeOAuthState(returned: string | null): boolean {
  try {
    const stored = sessionStorage.getItem(KEY);
    sessionStorage.removeItem(KEY);
    return returned !== null && stored !== null && returned === stored;
  } catch {
    return false;
  }
}
