/**
 * Tells a sideloaded Android build that a newer one exists. The stores do
 * this for their apps; an APK installed from lexpad.app has nobody to tell
 * it, so once a day the app reads a tiny version file from the site and
 * remembers the answer. Nothing is sent, and a failure is silent: an old
 * build keeps working, it just does not know it is old.
 */
import { getMeta, setMeta } from '@/db/schema.js';
import { SITE_HOST, safeExternalUrl } from './externalLinks.js';
import { platform } from './platform/index.js';

export const VERSION_URL = `https://${SITE_HOST}/version.json`;
/** How long a check stands before the file is read again. */
export const CHECK_EVERY_MS = 24 * 60 * 60 * 1000;

export interface UpdateInfo {
  version: string;
  url: string;
}

interface VersionFile {
  android?: { versionName?: string; url?: string };
}

/** Whether `candidate` is a higher dotted version than `current`. */
export function isNewer(candidate: string, current: string): boolean {
  const a = candidate.split('.').map((part) => Number.parseInt(part, 10));
  const b = current.split('.').map((part) => Number.parseInt(part, 10));
  if (a.some(Number.isNaN) || b.some(Number.isNaN)) return false;
  for (let i = 0; i < Math.max(a.length, b.length); i += 1) {
    const x = a[i] ?? 0;
    const y = b[i] ?? 0;
    if (x !== y) return x > y;
  }
  return false;
}

/**
 * The newer build to offer, or null. Reads the site at most once a day and
 * only inside the Android shell; the web app updates itself and iOS will
 * come from a store.
 */
export async function checkForUpdate(
  now: number = Date.now(),
  fetchFn: typeof fetch = (input, init) => fetch(input, init),
): Promise<UpdateInfo | null> {
  if (!platform.env.embedded || platform.env.platform !== 'android') return null;
  const current = platform.env.appVersion;
  const known = await getMeta('updateCheck');
  if (known !== null && now - known.at < CHECK_EVERY_MS) {
    return isNewer(known.version, current) ? { version: known.version, url: known.url } : null;
  }
  if (!platform.network.online) return null;
  let latest: UpdateInfo | undefined;
  try {
    const response = await fetchFn(VERSION_URL, { cache: 'no-store' });
    if (!response.ok) return null;
    const file = (await response.json()) as VersionFile;
    const version = file.android?.versionName;
    const url = file.android?.url;
    if (typeof version !== 'string' || typeof url !== 'string') return null;
    // The banner opens this address, so a file that names anywhere but the
    // site's own download page is treated as no file at all.
    const safe = safeExternalUrl(url, 'update');
    if (safe === undefined) return null;
    latest = { version, url: safe.href };
  } catch {
    return null;
  }
  await setMeta('updateCheck', { at: now, ...latest });
  return isNewer(latest.version, current) ? latest : null;
}
