import { useEffect, useMemo, useRef, useState } from 'react';
import { useLocation, useNavigate } from 'react-router-dom';
import { LANGUAGES, directionOf } from '@lexpad/core';
import { Icon } from '@/components/ui/Icon.js';
import { t } from '@/i18n/index.js';
import { cx } from '@/lib/cx.js';
import { deviceLanguage, sampleFor, type Sample } from './samples.js';
import { markIntroSeen } from './seen.js';
import styles from './Intro.module.css';

const SLIDES = ['cards', 'boxes', 'ai'] as const;
type Slide = (typeof SLIDES)[number];

const COPY: Record<Slide, { title: Parameters<typeof t>[0]; body: Parameters<typeof t>[0] }> = {
  cards: { title: 'intro.cardsTitle', body: 'intro.cardsBody' },
  boxes: { title: 'intro.boxesTitle', body: 'intro.boxesBody' },
  ai: { title: 'intro.aiTitle', body: 'intro.aiBody' },
};

/** How far a finger must travel before it counts as a swipe. */
const SWIPE = 60;

/**
 * Three screens for someone who has never seen the app, shown once per
 * device before sign-in. Each screen is a live piece of the real interface
 * moving on its own, with one sentence under it: a card flipping, a word
 * climbing the boxes, the model filling a card. Skip is always there.
 */
export function Intro(): React.JSX.Element {
  const navigate = useNavigate();
  // Where the gate was taking the visitor; sign-in returns them there.
  const { state: carried } = useLocation() as { state: unknown };
  const [index, setIndex] = useState(0);
  const sample = useMemo(() => sampleFor(deviceLanguage()), []);
  const slide: Slide = SLIDES[index] ?? 'cards';
  const last = index === SLIDES.length - 1;
  const start = useRef<number | undefined>(undefined);

  const leave = (mode?: 'signup'): void => {
    markIntroSeen();
    void navigate(mode === 'signup' ? '/auth?mode=signup' : '/auth', { replace: true, state: carried });
  };
  const go = (delta: number): void => {
    setIndex((previous) => Math.min(SLIDES.length - 1, Math.max(0, previous + delta)));
  };

  return (
    <main className={styles.wrap}>
      <div className={styles.top}>
        <div className={styles.brand}>
          <span className={styles.mark}>
            <Icon name="notebook" size={18} weight={2} />
          </span>
          <span className={styles.name}>{t('app.name')}</span>
        </div>
        <button
          type="button"
          className={styles.skip}
          onClick={() => {
            leave();
          }}
        >
          {t('intro.skip')}
        </button>
      </div>

      <div
        className={styles.stage}
        onPointerDown={(event) => {
          start.current = event.clientX;
        }}
        onPointerUp={(event) => {
          if (start.current === undefined) return;
          const dx = event.clientX - start.current;
          start.current = undefined;
          if (dx < -SWIPE) go(1);
          else if (dx > SWIPE) go(-1);
        }}
      >
        {slide === 'cards' && <CardsDemo sample={sample} />}
        {slide === 'boxes' && <BoxesDemo sample={sample} />}
        {slide === 'ai' && <AiDemo sample={sample} />}
      </div>

      <div className={styles.copy} key={slide}>
        <h1 className={styles.title}>{t(COPY[slide].title)}</h1>
        <p className={styles.body}>{t(COPY[slide].body, { count: LANGUAGES.length })}</p>
      </div>

      <div
        className={styles.dots}
        role="img"
        aria-label={t('intro.step', { step: index + 1, total: SLIDES.length })}
      >
        {SLIDES.map((name, position) => (
          <span key={name} className={cx(styles.dot, position === index && styles.dotOn)} />
        ))}
      </div>

      <div className={styles.actions}>
        {last ? (
          <>
            <button
              type="button"
              className={styles.primary}
              onClick={() => {
                leave('signup');
              }}
            >
              {t('intro.create')}
            </button>
            <button
              type="button"
              className={styles.secondary}
              onClick={() => {
                leave();
              }}
            >
              {t('intro.haveAccount')}
            </button>
          </>
        ) : (
          <button
            type="button"
            className={styles.primary}
            onClick={() => {
              go(1);
            }}
          >
            {t('intro.next')}
            <Icon name="arrowRight" size={18} weight={2} />
          </button>
        )}
      </div>
    </main>
  );
}

/** A card that turns over on its own: word, then meaning. */
function CardsDemo({ sample }: { sample: Sample }): React.JSX.Element {
  const [flipped, setFlipped] = useState(false);
  useEffect(() => {
    const timer = window.setInterval(() => {
      setFlipped((previous) => !previous);
    }, 2600);
    return () => {
      window.clearInterval(timer);
    };
  }, []);
  return (
    <div className={styles.demo} aria-hidden="true">
      <div className={cx(styles.flipper, flipped && styles.flipped)}>
        <div className={cx(styles.face, styles.front)}>
          <span className={styles.kicker}>
            {t('intro.demoFlashcard')} · {t('onboarding.box', { n: 1 })}
            <span className={styles.kickerNew}>{t('session.new')}</span>
          </span>
          <span className={styles.word}>{sample.headword}</span>
          <span className={styles.pron}>{sample.pronunciation}</span>
          <span className={styles.speaker}>
            <Icon name="speaker" size={18} weight={1.9} />
          </span>
          <span className={styles.hint}>{t('session.tapToFlip')}</span>
        </div>
        <div className={cx(styles.face, styles.back)}>
          <span className={styles.backHead}>
            <span>
              <span className={styles.backWord}>{sample.headword}</span>
              <span className={styles.backMeta}>{`${sample.pos} · ${sample.level}`}</span>
            </span>
            <span className={styles.aiSpeak}>
              <Icon name="speaker" size={15} weight={1.9} />
            </span>
          </span>
          <span className={styles.meaning} lang={sample.meaningLang} dir={directionOf(sample.meaningLang)}>
            {sample.meaning}
          </span>
          <span className={styles.example}>
            <span>{sample.example}</span>
            <span className={styles.aiSpeak}>
              <Icon name="speaker" size={14} weight={1.9} />
            </span>
          </span>
          <span className={styles.grades}>
            <span className={styles.wrong}>{t('session.didntKnow')}</span>
            <span className={styles.right}>{t('session.knewIt')}</span>
          </span>
        </div>
      </div>
    </div>
  );
}

const HOP: readonly { box: number; caption: Parameters<typeof t>[0]; tone: 'new' | 'right' | 'wrong' }[] = [
  { box: 0, caption: 'intro.hopNew', tone: 'new' },
  { box: 1, caption: 'intro.hopUp', tone: 'right' },
  { box: 2, caption: 'intro.hopUp', tone: 'right' },
  { box: 0, caption: 'intro.hopBack', tone: 'wrong' },
];
const HEIGHTS = [26, 42, 58, 78, 100] as const;

/** The five boxes, with the word hopping up on right answers and falling back on a wrong one. */
function BoxesDemo({ sample }: { sample: Sample }): React.JSX.Element {
  const [phase, setPhase] = useState(0);
  useEffect(() => {
    const timer = window.setInterval(() => {
      setPhase((previous) => (previous + 1) % HOP.length);
    }, 1900);
    return () => {
      window.clearInterval(timer);
    };
  }, []);
  const step: (typeof HOP)[number] = HOP[phase] ?? { box: 0, caption: 'intro.hopNew', tone: 'new' };
  return (
    <div className={styles.demo} aria-hidden="true">
      <div className={styles.boxes}>
        <div className={styles.track}>
          <span
            className={cx(
              styles.chip,
              step.tone === 'wrong' && styles.chipWrong,
              step.tone === 'right' && styles.chipRight,
            )}
            style={{ transform: `translateX(calc(${String(step.box)} * (100% + 8px)))` }}
          >
            {sample.headword}
          </span>
        </div>
        <div className={styles.bars}>
          {HEIGHTS.map((height, position) => (
            <div key={position} className={styles.column}>
              <div
                className={cx(styles.bar, position === step.box && styles.barOn)}
                style={{ height: `${String(height)}%`, opacity: 0.4 + position * 0.15 }}
              />
              <span className={styles.barLabel}>{t('onboarding.box', { n: position + 1 })}</span>
            </div>
          ))}
        </div>
        <p
          key={phase}
          className={cx(
            styles.caption,
            step.tone === 'right' && styles.captionRight,
            step.tone === 'wrong' && styles.captionWrong,
          )}
        >
          {t(step.caption)}
        </p>
      </div>
    </div>
  );
}

/** A word typing itself, then the card the model writes for it, laid out like the word screen. */
function AiDemo({ sample }: { sample: Sample }): React.JSX.Element {
  // Letters arrive one per tick; then the card's parts, one every other
  // tick, in the order the model returns them; then a pause and again.
  const letters = sample.headword.length;
  const parts = 2 + sample.senses.length * 2 + 1;
  const total = letters + parts * 2 + 8;
  const [tick, setTick] = useState(0);
  useEffect(() => {
    const timer = window.setInterval(() => {
      setTick((previous) => (previous >= total ? 0 : previous + 1));
    }, 230);
    return () => {
      window.clearInterval(timer);
    };
  }, [total]);
  const typed = sample.headword.slice(0, Math.min(tick, letters));
  const shown = Math.max(0, Math.floor((tick - letters) / 2));
  const dir = directionOf(sample.meaningLang);
  return (
    <div className={styles.demo} aria-hidden="true">
      <div className={styles.aiCard}>
        <div className={styles.aiInput}>
          <span className={styles.aiTyped}>
            {typed}
            <span className={styles.caret} />
          </span>
          <span className={cx(styles.aiButton, shown > 0 && styles.aiButtonBusy)}>
            <Icon name="sparkles" size={14} weight={2} />
            {shown > 0 && shown < parts ? t('ai.working') : t('onboarding.fillWithAi')}
          </span>
        </div>
        <div className={styles.aiLines}>
          {shown >= 1 && (
            <span className={cx(styles.aiLine, styles.aiHead)}>
              <span className={styles.aiWord}>{sample.headword}</span>
              <span className={styles.aiSpeak}>
                <Icon name="speaker" size={15} weight={1.9} />
              </span>
            </span>
          )}
          {shown >= 2 && (
            <span
              className={cx(styles.aiLine, styles.aiMeta)}
            >{`${sample.pronunciation} · ${sample.pos} · ${sample.level}`}</span>
          )}
          {sample.senses.map((sense, position) => {
            const at = 3 + position * 2;
            if (shown < at) return null;
            return (
              <span key={sense.meaning} className={cx(styles.aiSense, position > 0 && styles.aiSenseNext)}>
                <span className={cx(styles.aiLine, styles.aiMeaning)}>
                  <span className={styles.aiSenseNumber}>{position + 1}</span>
                  <span lang={sample.meaningLang} dir={dir}>
                    {sense.meaning}
                  </span>
                </span>
                {shown >= at + 1 && (
                  <span className={cx(styles.aiLine, styles.aiExample)}>
                    <span>{sense.example}</span>
                    <span className={styles.aiSpeak}>
                      <Icon name="speaker" size={14} weight={1.9} />
                    </span>
                  </span>
                )}
              </span>
            );
          })}
          {shown >= parts && (
            <span className={cx(styles.aiLine, styles.aiChips)}>
              {sample.collocations.map((chip) => (
                <span key={chip} className={styles.aiChip}>
                  {chip}
                </span>
              ))}
            </span>
          )}
        </div>
      </div>
    </div>
  );
}
