/**
 * Seals the browser extension's session before it crosses `window.postMessage`.
 *
 * Everything posted on this window reaches every listener in the document:
 * other extensions' content scripts and the third-party scripts the app
 * loads (Paddle, Apple). So the tokens are never posted in the clear. The
 * extension opens `/connect-extension?state=…&key=…`, where `key` is the
 * public half of an ECDH P-256 pair whose private half never leaves its
 * background. This page makes its own pair, derives an AES-GCM key from the
 * shared secret (HKDF-SHA-256, bound to `state`) and posts only the sealed
 * box. Whoever else is listening sees a public key, an IV and ciphertext.
 *
 * The extension's side is `src/lib/handoff.ts` in `lexpad_extension`. The
 * constants below must match it exactly; change both or neither.
 */

/** The sealed-box version both sides speak. */
export const SEAL_VERSION = 1;
/** Prefix of the HKDF info; `state` follows it. Mirrors the extension. */
export const SEAL_INFO = 'lexpad-extension-connect v1 ';

const EC = { name: 'ECDH', namedCurve: 'P-256' } as const;
/** An uncompressed P-256 point: 0x04, then 32 bytes each of x and y. */
const RAW_KEY_BYTES = 65;

/** What is posted instead of a session. Every field is base64url. */
export interface SealedSession {
  v: number;
  key: string;
  iv: string;
  data: string;
}

/** The session as the extension keeps it, before it adds an expiry time. */
export interface HandedSession {
  accessToken: string;
  expiresIn: number;
  refreshToken: string;
  user: { id: string; email: string; displayName: string };
}

export function toBase64Url(bytes: ArrayBuffer | Uint8Array): string {
  const view = bytes instanceof Uint8Array ? bytes : new Uint8Array(bytes);
  let binary = '';
  for (const byte of view) binary += String.fromCharCode(byte);
  return btoa(binary).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
}

export function fromBase64Url(text: string): Uint8Array<ArrayBuffer> {
  if (!/^[A-Za-z0-9_-]*$/.test(text)) throw new Error('not base64url');
  const padded = text.replace(/-/g, '+').replace(/_/g, '/') + '='.repeat((4 - (text.length % 4)) % 4);
  const binary = atob(padded);
  const out = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i += 1) out[i] = binary.charCodeAt(i);
  return out;
}

/**
 * The extension's public key from the address, or undefined when it is not
 * one. Checked before a session is opened, so a bad address never mints a
 * session that nobody can receive.
 */
export async function extensionKey(raw: string | null): Promise<CryptoKey | undefined> {
  if (raw === null || raw === '') return undefined;
  try {
    const bytes = fromBase64Url(raw);
    if (bytes.length !== RAW_KEY_BYTES) return undefined;
    return await crypto.subtle.importKey('raw', bytes, EC, false, []);
  } catch {
    return undefined;
  }
}

/** The AES-GCM key both sides derive from their ECDH secret, bound to `state`. */
export async function sharedKey(
  privateKey: CryptoKey,
  peerPublicKey: CryptoKey,
  state: string,
  usage: 'encrypt' | 'decrypt',
): Promise<CryptoKey> {
  const secret = await crypto.subtle.deriveBits({ name: 'ECDH', public: peerPublicKey }, privateKey, 256);
  const hkdf = await crypto.subtle.importKey('raw', secret, 'HKDF', false, ['deriveKey']);
  return crypto.subtle.deriveKey(
    {
      name: 'HKDF',
      hash: 'SHA-256',
      salt: new Uint8Array(0),
      info: new TextEncoder().encode(SEAL_INFO + state),
    },
    hkdf,
    { name: 'AES-GCM', length: 256 },
    false,
    [usage],
  );
}

/** Seals `session` so that only the extension holding the private half of `peer` can open it. */
export async function sealSession(
  session: HandedSession,
  state: string,
  peer: CryptoKey,
): Promise<SealedSession> {
  const mine = await crypto.subtle.generateKey(EC, true, ['deriveBits']);
  const key = await sharedKey(mine.privateKey, peer, state, 'encrypt');
  const iv = crypto.getRandomValues(new Uint8Array(12));
  const data = await crypto.subtle.encrypt(
    { name: 'AES-GCM', iv, additionalData: new TextEncoder().encode(state) },
    key,
    new TextEncoder().encode(JSON.stringify(session)),
  );
  return {
    v: SEAL_VERSION,
    key: toBase64Url(await crypto.subtle.exportKey('raw', mine.publicKey)),
    iv: toBase64Url(iv),
    data: toBase64Url(data),
  };
}
