import { lazy, Suspense, useEffect, useId, useState } from 'react';
import { Link, useLocation, useNavigate } from 'react-router-dom';
import { ADD_WORD_PATH, DECKS_PLACE, TABS, tabMatches } from '@/components/layout/nav.js';
import { Icon, type IconName } from '@/components/ui/Icon.js';
import { t } from '@/i18n/index.js';
import { cx } from '@/lib/cx.js';
import { currentDevice } from '@/lib/platform/device.js';
import { sidebarState, useSidebarStore } from '@/lib/sidebar.js';
import { useCurrentDay } from '@/lib/useCurrentDay.js';
import { useLiveQuery } from '@/lib/useLiveQuery.js';
import { useShowsKeys, useWindowClass } from '@/lib/windowClass.js';
import { useAuth } from '@/features/auth/session.js';
import { LANGUAGE_NAMES } from '@/features/settings/data.js';
import { settingsPath } from '@/features/settings/paths.js';
import { SRS_OFF, loadSrsView } from '@/features/schedule/data.js';
import { shownModes } from '@/features/modes/data.js';
import { SIDEBAR_LOADING, loadSidebar, type SidebarData } from './data.js';
import { isAddWordKey, isToggleKey, isTyping, modifierLabel } from './keys.js';
import styles from './Sidebar.module.css';

/** Fetched on first use, as the notebook chip does: Today should not wait for it. */
const NotebookSheet = lazy(() =>
  import('@/features/notebook/NotebookSheet.js').then((module) => ({ default: module.NotebookSheet })),
);

/** A due count wider than this reads as a smudge in a badge; the label keeps the number. */
const BADGE_MAX = 99;

/**
 * The navigation on a tablet or a computer: a sidebar down the side, in
 * place of the bottom bar a phone has. It folds into a rail of icons and
 * opens out again (Material 3's expanded and collapsed navigation rail; the
 * sidebar of a Mac or iPad app), and the device remembers which
 * (lib/sidebar.ts). Wide windows start open, tablets start folded.
 *
 * From the top:
 * - the name, and the toggle;
 * - **Add a word**, filled in the brand colour, the most visible thing on
 *   the screen, because it is the thing people come to do (owner,
 *   2026-10-07: the old outlined button was hard to find). N does it too;
 * - the notebook in view, which opens the notebook sheet — the same sheet
 *   Settings, Today and the notebook open;
 * - the five places, from the same list as the bottom bar, with Today's own
 *   count of what is due on Today;
 * - the streak, once there is one;
 * - Lexpad everywhere and the account, at the foot, where apps keep them.
 *
 * Every number here is one Today shows too, read the same way. Nothing is
 * drawn until it is read: a zero that is not real is worse than a gap.
 *
 * Folded, everything without a visible label has a tooltip that is also its
 * accessible name, so a mouse, a keyboard and a screen reader all get the
 * same words. Logical properties throughout, so right-to-left mirrors.
 */
export function Sidebar(): React.JSX.Element {
  const { pathname } = useLocation();
  const navigate = useNavigate();
  const size = useWindowClass();
  const choice = useSidebarStore((store) => store.choice);
  const choose = useSidebarStore((store) => store.choose);
  const state = sidebarState(size, choice);
  const expanded = state === 'expanded';
  const showsKeys = useShowsKeys();
  const [mac] = useState(() => {
    const os = currentDevice().os;
    return os === 'mac' || os === 'ios';
  });
  const now = useCurrentDay();
  const data = useLiveQuery<SidebarData | undefined>(() => loadSidebar(now), SIDEBAR_LOADING, [now]);
  const user = useAuth((store) => store.user);
  // Decks joins the places, under Notebook, once games and drills are on (SRS v2).
  const srs = useLiveQuery(loadSrsView, SRS_OFF, []);
  const places =
    shownModes(srs).length > 0
      ? TABS.flatMap((tab) => (tab.to === '/notebook' ? [tab, DECKS_PLACE] : [tab]))
      : TABS;
  const [sheet, setSheet] = useState(false);
  // Escape puts tooltips away until the pointer or focus moves again
  // (WCAG 1.4.13: content shown on hover can be dismissed).
  const [tipsAway, setTipsAway] = useState(false);

  const toggle = (): void => {
    choose(expanded ? 'collapsed' : 'expanded');
  };

  useEffect(() => {
    const onKeyDown = (event: KeyboardEvent): void => {
      if (event.defaultPrevented || event.repeat) return;
      if (isToggleKey(event)) {
        event.preventDefault();
        choose(
          sidebarState(size, useSidebarStore.getState().choice) === 'expanded' ? 'collapsed' : 'expanded',
        );
        return;
      }
      if (event.key === 'Escape') {
        setTipsAway(true);
        return;
      }
      // A dialog owns the keyboard while it is open, and a field owns letters.
      if (isTyping(event.target) || document.querySelector('[aria-modal="true"]') !== null) return;
      if (isAddWordKey(event)) {
        event.preventDefault();
        void navigate(ADD_WORD_PATH);
      }
    };
    window.addEventListener('keydown', onKeyDown);
    return () => {
      window.removeEventListener('keydown', onKeyDown);
    };
  }, [choose, navigate, size]);

  const toggleKeys = `${mac ? 'Meta' : 'Control'}+\\`;
  const toggleLabel = expanded ? t('sidebar.collapse') : t('sidebar.expand');
  const name = user?.displayName.trim() ?? '';
  const notebookName = data === undefined ? '' : data.all ? t('notebooks.all') : (data.notebook?.title ?? '');
  const notebookLine =
    data === undefined
      ? ''
      : data.all
        ? t('settings.notebooksCount', { count: data.notebooks })
        : data.notebook === undefined
          ? ''
          : t('today.heroLanguages', {
              target: LANGUAGE_NAMES[data.notebook.targetLang],
              meaning: LANGUAGE_NAMES[data.notebook.meaningLang],
            });

  return (
    <nav
      className={cx(styles.rail, tipsAway && styles.tipsAway)}
      aria-label={t('nav.label')}
      data-variant="rail"
      data-state={state}
      onPointerMove={() => {
        if (tipsAway) setTipsAway(false);
      }}
      onFocus={() => {
        if (tipsAway) setTipsAway(false);
      }}
    >
      <div className={styles.head}>
        <span className={styles.brand} aria-hidden="true">
          <span className={styles.logo}>
            <Icon name="notebook" size={16} weight={2.2} />
          </span>
          <span className={styles.brandName}>{t('app.name')}</span>
        </span>
        <Tipped
          expanded={expanded}
          always
          label={toggleLabel}
          hint={showsKeys ? `${modifierLabel(mac)} \\` : undefined}
        >
          {(labelledBy) => (
            <button
              type="button"
              className={styles.toggle}
              aria-labelledby={labelledBy}
              aria-expanded={expanded}
              aria-keyshortcuts={toggleKeys}
              onClick={toggle}
            >
              <Icon name="sidebar" size={20} className={styles.toggleIcon} />
            </button>
          )}
        </Tipped>
      </div>

      <Tipped expanded={expanded} label={t('add.title')} hint={showsKeys ? 'N' : undefined}>
        {(labelledBy) => (
          <button
            type="button"
            className={styles.add}
            aria-labelledby={labelledBy}
            aria-label={labelledBy === undefined ? t('add.title') : undefined}
            aria-keyshortcuts="N"
            onClick={() => {
              void navigate(ADD_WORD_PATH);
            }}
          >
            <Icon name="plus" size={22} weight={2.4} />
            <span className={styles.addLabel} aria-hidden="true">
              {t('add.title')}
            </span>
            {showsKeys && (
              <kbd className={styles.kbd} aria-hidden="true">
                N
              </kbd>
            )}
          </button>
        )}
      </Tipped>

      {notebookName !== '' && (
        <Tipped expanded={expanded} label={notebookName} detail={t('notebooks.open')}>
          {(labelledBy) => (
            <button
              type="button"
              className={styles.notebook}
              aria-labelledby={labelledBy}
              aria-label={labelledBy === undefined ? `${t('notebooks.open')}: ${notebookName}` : undefined}
              aria-haspopup="dialog"
              onClick={() => {
                setSheet(true);
              }}
            >
              <span className={styles.notebookMark}>
                <Icon name="notebook" size={18} weight={2} />
              </span>
              <span className={styles.notebookText} aria-hidden="true">
                <span className={styles.notebookName} dir="auto">
                  {notebookName}
                </span>
                {notebookLine !== '' && <span className={styles.notebookLine}>{notebookLine}</span>}
              </span>
              <Icon name="chevronDown" size={16} weight={2.2} className={styles.notebookGo} />
            </button>
          )}
        </Tipped>
      )}

      <div className={styles.scroll}>
        <div className={styles.items}>
          {places.map((tab) => {
            const current = tabMatches(tab, pathname);
            const due = tab.to === '/' && data !== undefined && data.due > 0 ? data.due : 0;
            return (
              <Link
                key={tab.to}
                to={tab.to}
                className={cx(styles.item, current && styles.current)}
                aria-current={current ? 'page' : undefined}
              >
                <span className={styles.pill}>
                  <Icon name={tab.icon} size={20} />
                  {due > 0 && (
                    <span className={styles.badge} aria-hidden="true">
                      {due > BADGE_MAX ? `${String(BADGE_MAX)}+` : due}
                    </span>
                  )}
                </span>
                <span className={styles.label}>{t(tab.label)}</span>
                {due > 0 && <span className="sr-only">{t('sidebar.due', { count: due })}</span>}
              </Link>
            );
          })}
        </div>

        {expanded && data !== undefined && data.streak > 0 && (
          <p className={cx(styles.streak, data.streakActive && styles.streakLive)}>
            <Icon name="flame" size={18} className={styles.flame} />
            <span>
              <span className={styles.streakCount}>{data.streak}</span>{' '}
              {data.streakActive ? t('today.streak') : t('today.streakKeep')}
            </span>
          </p>
        )}
      </div>

      <div className={styles.foot}>
        <FootLink
          expanded={expanded}
          to={settingsPath('everywhere')}
          icon="grid"
          label={t('everywhere.title')}
        />
        <Tipped expanded={expanded} label={name === '' ? t('settings.account') : name} detail={user?.email}>
          {(labelledBy) => (
            <Link to={settingsPath('account')} className={styles.account} aria-labelledby={labelledBy}>
              <span className={styles.avatar} aria-hidden="true">
                {initialOf(name === '' ? (user?.email ?? '') : name)}
              </span>
              <span className={styles.accountText}>
                <span className={styles.accountName} dir="auto">
                  {name === '' ? t('settings.account') : name}
                </span>
                {user !== null && <span className={styles.accountEmail}>{user.email}</span>}
              </span>
            </Link>
          )}
        </Tipped>
      </div>

      {sheet && (
        <Suspense fallback={null}>
          <NotebookSheet
            activeId={data?.all === true ? undefined : data?.notebook?.id}
            onClose={() => {
              setSheet(false);
            }}
          />
        </Suspense>
      )}
    </nav>
  );
}

/** A link at the foot: icon and label open, icon and tooltip folded. */
function FootLink({
  expanded,
  to,
  icon,
  label,
}: {
  expanded: boolean;
  to: string;
  icon: IconName;
  label: string;
}): React.JSX.Element {
  return (
    <Tipped expanded={expanded} label={label}>
      {(labelledBy) => (
        <Link
          to={to}
          className={styles.footLink}
          aria-labelledby={labelledBy}
          aria-label={labelledBy === undefined ? label : undefined}
        >
          <span className={styles.footIcon}>
            <Icon name={icon} size={20} />
          </span>
          <span className={styles.footLabel} aria-hidden="true">
            {label}
          </span>
        </Link>
      )}
    </Tipped>
  );
}

/**
 * A control with a tooltip beside it while the sidebar is folded (or
 * always, for the toggle, whose label is never written out). The tooltip's
 * words are the control's accessible name, through `aria-labelledby`, so
 * what a mouse sees on hover is what a screen reader says; the key hint is
 * left out of the name and given by `aria-keyshortcuts` instead. Open, the
 * control carries its own label and there is no tooltip.
 *
 * The wrapper is always there, so folding the sidebar never remounts the
 * control and focus stays where it was.
 */
function Tipped({
  expanded,
  always = false,
  label,
  detail,
  hint,
  children,
}: {
  expanded: boolean;
  always?: boolean;
  label: string;
  detail?: string | undefined;
  hint?: string | undefined;
  children: (labelledBy: string | undefined) => React.ReactNode;
}): React.JSX.Element {
  const id = useId();
  const tipped = always || !expanded;
  const hasDetail = detail !== undefined && detail !== '';
  const labelledBy = hasDetail ? `${id}-label ${id}-detail` : `${id}-label`;
  return (
    <span className={styles.tipped}>
      {children(tipped ? labelledBy : undefined)}
      {tipped && (
        <span className={styles.tip} role="tooltip" id={id}>
          <span className={styles.tipLabel} id={`${id}-label`} dir="auto">
            {label}
          </span>
          {hasDetail && (
            <span className={styles.tipDetail} id={`${id}-detail`} dir="auto">
              {detail}
            </span>
          )}
          {hint !== undefined && (
            <kbd className={styles.tipKey} aria-hidden="true">
              {hint}
            </kbd>
          )}
        </span>
      )}
    </span>
  );
}

/** The first letter of a name, for the round mark (as on the Settings card). */
function initialOf(text: string): string {
  const first = Array.from(text.trim())[0];
  return first === undefined ? '' : first.toLocaleUpperCase();
}
