/**
 * The sync status the UI shows: a dot on the greeting when work is queued,
 * a line in Settings, and nothing else. Sync itself never blocks a screen.
 *
 * This is also the one place that decides when this device talks to the
 * server about its data, and it is careful about how often: every learner
 * runs this loop, so a request here is a request times every learner.
 *
 * - A grade is a local write. Practice answers are pushed in batches
 *   (`syncPractice`): after `PRACTICE_BATCH_ANSWERS` answers, after
 *   `PRACTICE_BATCH_MS`, when the session ends, and when the page is hidden
 *   or closed. An answer taken back before its batch went never reaches the
 *   server at all.
 * - A pull brings other devices' changes, so it happens when there may be
 *   some: on opening the app, at the start and end of a session, when the
 *   app comes back to the foreground, and every few minutes while it is
 *   shown. A pull younger than `FRESH_PULL_MS` (any tab's: the time is in the
 *   shared database) is not repeated.
 * - A failed run waits before the next, with exponential backoff and full
 *   jitter (`SYNC_BACKOFF_BASE_MS` up to `SYNC_BACKOFF_CAP_MS`, never less
 *   than the server's `Retry-After`), so an outage or a deploy is not met by
 *   every client at once when it ends. Only the learner's own "Sync now"
 *   goes past the wait.
 */
import { create } from 'zustand';
import { ApiError, isApiError } from '@/api/errors.js';
import { outboxSize, parkedCount, unparkAll } from '@/db/repo.js';
import { getMeta } from '@/db/schema.js';
import { backoffDelay } from '@/lib/backoff.js';
import { platform } from '@/lib/platform/index.js';
import { checkForUpdate } from '@/lib/updates.js';
import { syncReminder } from './reminder.js';
import { runSync } from './worker.js';

/**
 * How long the loop waits between pulls while the app is open and shown: a
 * random point in this range, so the tabs of a crowd that opened together
 * do not stay in step. Another device's change shows up within a few
 * minutes; coming back to the app pulls at once.
 */
export const IDLE_PULL_MIN_MS = 3 * 60_000;
export const IDLE_PULL_MAX_MS = 5 * 60_000;

/**
 * A pull younger than this is not repeated on focus, at the start or end of
 * a session, or after an edit. Read from the shared database, so a pull in
 * another tab counts.
 */
export const FRESH_PULL_MS = 60_000;

/**
 * How long `syncSoon` waits for local changes to stop arriving before it
 * syncs. One push per burst of edits is the point. A timing choice of this
 * client, not a value the server or the learner owns.
 */
export const SYNC_SOON_DEBOUNCE_MS = 1_500;

/**
 * The longest a practice answer waits locally before it is pushed, and how
 * many answers make a batch on their own. Answers are local writes that
 * the screen never waits for, so the only cost of waiting is how soon
 * another device sees them; the session's end and the page being hidden or
 * closed push whatever is left.
 */
export const PRACTICE_BATCH_MS = 30_000;
export const PRACTICE_BATCH_ANSWERS = 10;

/**
 * The backoff after a failed run: the first window, doubling with each
 * failure in a row, up to the cap. A client choice about how hard to press
 * a server that is down or overloaded; the server's own `Retry-After` is
 * the floor.
 */
export const SYNC_BACKOFF_BASE_MS = 30_000;
export const SYNC_BACKOFF_CAP_MS = 15 * 60_000;

/**
 * The Web Lock only one tab may hold while it syncs. Every tab shares one
 * IndexedDB, so one tab's push and pull serve them all; two at once would
 * push the same outbox items twice and apply the same changes twice.
 */
export const SYNC_LOCK = 'lexpad.sync';

/**
 * How long a sync somebody asked for waits behind another tab's before it
 * gives up. That tab is draining the same outbox, so giving up loses nothing;
 * the bound only keeps a stuck sibling from leaving this tab "syncing".
 */
const SYNC_LOCK_WAIT_MS = 60_000;

/**
 * `busy` is the server saying it is overloaded (503 or 429): the changes
 * are safe on this device and go when it has room.
 */
export type SyncPhase = 'idle' | 'syncing' | 'offline' | 'busy' | 'error';

interface SyncState {
  phase: SyncPhase;
  /** Changes waiting to be pushed. */
  queued: number;
  /** Changes set aside after repeated failures; see OutboxItem.parked. */
  parked: number;
  lastSyncAt: string | null;
  lastError: string | null;
  /**
   * Runs a full sync now, push and pull, past any backoff: this is somebody
   * asking. While one is running it queues a single run behind it instead
   * of starting a second beside it, and resolves when that one has
   * finished, so a change made mid-run has been pushed when it resolves.
   */
  syncNow: () => Promise<void>;
  /** Recounts the queue, after a local mutation. */
  refreshQueue: () => Promise<void>;
  /** Puts parked changes back in the queue and syncs. */
  retryParked: () => Promise<void>;
}

/** When to pull after the push. */
type PullWhen = 'always' | 'ifStale' | 'never';

/** What a caller wants from a run. */
interface Want {
  pull: PullWhen;
  /** For `ifStale`: how old the last pull may be before it is repeated. */
  freshMs: number;
  /**
   * Whether the caller has local changes that must go: it waits for another
   * tab's run and queues a run behind this tab's. Without, the caller only
   * wants a pull, and leaves the work to a run already going.
   */
  hasChanges: boolean;
  /** Somebody asked: go past the backoff. */
  force: boolean;
  /** The page is going away: let the requests outlive it. */
  keepalive: boolean;
}

const ASKED: Want = { pull: 'always', freshMs: 0, hasChanges: true, force: true, keepalive: false };

/** The strongest of two wants, for a run queued behind the current one. */
function merge(a: Want, b: Want): Want {
  const rank: Record<PullWhen, number> = { never: 0, ifStale: 1, always: 2 };
  const pull = rank[a.pull] >= rank[b.pull] ? a.pull : b.pull;
  return {
    pull,
    freshMs: Math.min(a.freshMs, b.freshMs),
    hasChanges: a.hasChanges || b.hasChanges,
    force: a.force || b.force,
    keepalive: a.keepalive || b.keepalive,
  };
}

/** The run in progress, if any. */
let current: Promise<void> | null = null;
/** The one run queued behind it, shared by everyone who asked meanwhile. */
let followUp: Promise<void> | null = null;
/** What that queued run will do: everything its callers asked for. */
let followUpWant: Want | null = null;
/** The pending `syncSoon` timer. */
let soonTimer: ReturnType<typeof setTimeout> | undefined;

/** Practice answers written since the last push of them, in this tab. */
let practiceAnswers = 0;
/** The timer that pushes them if the batch does not fill first. */
let practiceTimer: ReturnType<typeof setTimeout> | undefined;

/** Failed runs in a row. */
let failures = 0;
/** No run the loop starts before this; see the backoff above. */
let blockedUntil = 0;
/** Whether the last failure was the network rather than the server. */
let failedOffline = false;
/** The run that comes after the backoff. */
let retryTimer: ReturnType<typeof setTimeout> | undefined;

export const useSync = create<SyncState>((set, get) => ({
  phase: 'idle',
  queued: 0,
  parked: 0,
  lastSyncAt: null,
  lastError: null,

  async refreshQueue() {
    set({ queued: await outboxSize(), parked: await parkedCount() });
  },

  async retryParked() {
    await unparkAll();
    await get().refreshQueue();
    await get().syncNow();
  },

  syncNow() {
    return startOrJoin(ASKED);
  },
}));

function startOrJoin(want: Want): Promise<void> {
  if (current !== null) {
    // A pull only: the run going will do.
    if (!want.hasChanges) return current;
    // Two runs side by side would push the same outbox items twice. The
    // running one may have read the queue before the caller's change was
    // written, so one more run follows it, and only one.
    followUpWant = followUpWant === null ? want : merge(followUpWant, want);
    followUp ??= current.then(() => {
      const next = followUpWant ?? want;
      followUp = null;
      followUpWant = null;
      return startOrJoin(next);
    });
    return followUp;
  }
  const started = run(want).finally(() => {
    current = null;
  });
  current = started;
  return started;
}

/** One sync, start to finish. Never throws; the outcome is the phase. */
async function run(want: Want): Promise<void> {
  const set = useSync.setState;
  if (!platform.network.online) {
    set({ phase: 'offline' });
    return;
  }
  // Waiting out a failure: the run after the backoff is already set.
  if (!want.force && Date.now() < blockedUntil) return;
  try {
    const result = { pulled: false };
    const ran = await withSyncLock(want.hasChanges, async () => {
      set({ phase: 'syncing', lastError: null });
      const outcome = await runSync({
        shouldPull: () => shouldPull(want),
        ...(want.force ? { pullAfterFailure: true } : {}),
        ...(want.keepalive ? { send: { keepalive: true } } : {}),
      });
      result.pulled = outcome.pulled;
    });
    if (ran) recovered();
    if (ran && result.pulled) {
      // A reminder time changed elsewhere reaches this device through the pull.
      void syncReminder().catch(() => undefined);
      // A sideloaded Android build learns about a newer one here, at most once a day.
      void checkForUpdate().catch(() => undefined);
      // Which SRS v2 features apply here; re-read only when the copy is stale.
      // Loaded on demand, so the API client it needs stays out of the entry.
      void import('./srs.js').then((srs) => srs.refreshSrs()).catch(() => undefined);
    }
    // Another tab may have done the work; its time is in the shared database.
    set({ ...(ran ? { phase: 'idle' as const } : {}), lastSyncAt: await getMeta('lastSyncAt') });
  } catch (error) {
    const offline = isApiError(error, 'offline');
    const busy = error instanceof ApiError && (error.busy || error.kind === 'tooMany');
    set({
      phase: offline ? 'offline' : busy ? 'busy' : 'error',
      lastError: offline || busy ? null : error instanceof Error ? error.message : 'sync failed',
    });
    backOff(error);
  } finally {
    // The count was taken before the push; take it again, or the
    // "1 change waiting" line outlives the change it counts.
    await useSync
      .getState()
      .refreshQueue()
      .catch(() => undefined);
  }
}

/** Whether this run should pull after its push. */
async function shouldPull(want: Want): Promise<boolean> {
  if (want.pull === 'always') return true;
  if (want.pull === 'never') return false;
  const last = await getMeta('lastSyncAt');
  if (last === null) return true;
  const at = Date.parse(last);
  return Number.isNaN(at) || Date.now() - at >= want.freshMs;
}

/** A run went through: the backoff is over. */
function recovered(): void {
  failures = 0;
  blockedUntil = 0;
  failedOffline = false;
  clearTimeout(retryTimer);
  retryTimer = undefined;
}

/**
 * A run failed: the next one the loop starts waits a random time in a
 * window that doubles with each failure in a row, plus whatever the server
 * asked for, and then runs by itself. A device that is plainly offline sets
 * no timer: coming back online starts the next run.
 */
function backOff(error: unknown): void {
  failures += 1;
  failedOffline = isApiError(error, 'offline');
  const floorMs = error instanceof ApiError ? (error.retryAfterMs ?? 0) : 0;
  const delay = backoffDelay(failures - 1, {
    baseMs: SYNC_BACKOFF_BASE_MS,
    capMs: SYNC_BACKOFF_CAP_MS,
    floorMs,
  });
  blockedUntil = Date.now() + delay;
  clearTimeout(retryTimer);
  retryTimer = setTimeout(() => {
    retryTimer = undefined;
    if (!platform.network.online) return;
    void startOrJoin({
      pull: 'ifStale',
      freshMs: FRESH_PULL_MS,
      hasChanges: true,
      force: false,
      keepalive: false,
    });
  }, delay);
}

/**
 * Runs `work` holding the sync lock and says whether it ran. A run with no
 * changes of its own that finds the lock taken leaves it to the holder. A
 * browser without Web Locks runs it as before; a native shell has one web
 * view, so the lock is always free there.
 */
async function withSyncLock(waits: boolean, work: () => Promise<void>): Promise<boolean> {
  // Absent in old browsers, and null in some test environments.
  const locks = globalThis.navigator.locks as LockManager | null | undefined;
  if (locks == null) {
    await work();
    return true;
  }
  if (!waits) {
    return locks.request(SYNC_LOCK, { ifAvailable: true }, async (lock) => {
      if (lock === null) return false;
      await work();
      return true;
    });
  }
  try {
    return await locks.request(SYNC_LOCK, { signal: AbortSignal.timeout(SYNC_LOCK_WAIT_MS) }, async () => {
      await work();
      return true;
    });
  } catch (error) {
    // Waited out: another tab has been syncing this same database all along.
    if (error instanceof DOMException && (error.name === 'TimeoutError' || error.name === 'AbortError')) {
      return false;
    }
    throw error;
  }
}

/** A random wait between idle pulls. */
function idleWait(): number {
  return IDLE_PULL_MIN_MS + Math.floor(Math.random() * (IDLE_PULL_MAX_MS - IDLE_PULL_MIN_MS));
}

/**
 * Starts the background loop: a full sync now, a pull every few minutes
 * while the app is shown, one when it is shown again or a shell returns to
 * the foreground, and one when the network comes back. When the page is
 * hidden or closed, whatever is queued is pushed with requests that outlive
 * it. Every run fails quietly when offline. Only one tab syncs at a time
 * (see `SYNC_LOCK`). Returns a stop function.
 */
export function startSync(): () => void {
  const pullIfStale = (freshMs: number): void => {
    void startOrJoin({ pull: 'ifStale', freshMs, hasChanges: false, force: false, keepalive: false });
  };

  void startOrJoin({ pull: 'always', freshMs: 0, hasChanges: false, force: false, keepalive: false });

  let idleTimer: ReturnType<typeof setTimeout> | undefined;
  const armIdle = (): void => {
    idleTimer = setTimeout(() => {
      // Nobody is looking, and the shown tab or the next visit will catch up.
      if (document.visibilityState !== 'hidden') pullIfStale(IDLE_PULL_MIN_MS);
      armIdle();
    }, idleWait());
  };
  armIdle();

  const offNetwork = platform.network.onChange((online) => {
    if (!online) {
      useSync.setState({ phase: 'offline' });
      return;
    }
    // The device was offline, not the server down: there is nothing to wait for.
    if (failedOffline) recovered();
    void startOrJoin({
      pull: 'ifStale',
      freshMs: FRESH_PULL_MS,
      hasChanges: true,
      force: false,
      keepalive: false,
    });
  });
  const onVisibility = (): void => {
    if (document.visibilityState === 'visible') pullIfStale(FRESH_PULL_MS);
    else void flushQueued();
  };
  document.addEventListener('visibilitychange', onVisibility);
  const onPageHide = (): void => {
    void flushQueued();
  };
  window.addEventListener('pagehide', onPageHide);
  // A shell's resume is a sync whatever the web view says about visibility.
  const offResume = platform.lifecycle.onResume(() => {
    pullIfStale(FRESH_PULL_MS);
  });

  return () => {
    clearTimeout(idleTimer);
    offNetwork();
    offResume();
    document.removeEventListener('visibilitychange', onVisibility);
    window.removeEventListener('pagehide', onPageHide);
  };
}

/**
 * Pushes everything queued, with requests that outlive the page: it is
 * being hidden or closed, and a phone may freeze or kill it next.
 */
function flushQueued(): Promise<void> {
  clearPracticeBatch();
  if (!platform.network.online) return Promise.resolve();
  return startOrJoin({ pull: 'never', freshMs: 0, hasChanges: true, force: false, keepalive: true });
}

/**
 * Syncs shortly after a local change, without waiting for the timer. The
 * queue is recounted at once so the dot appears; the sync waits until changes
 * stop arriving for `SYNC_SOON_DEBOUNCE_MS`, pushes them, and pulls only if
 * the last pull is older than `FRESH_PULL_MS`, so a burst of edits is one
 * push, never two runs at once.
 */
export async function syncSoon(): Promise<void> {
  await useSync.getState().refreshQueue();
  if (!platform.network.online) return;
  clearTimeout(soonTimer);
  soonTimer = setTimeout(() => {
    soonTimer = undefined;
    void startOrJoin({
      pull: 'ifStale',
      freshMs: FRESH_PULL_MS,
      hasChanges: true,
      force: false,
      keepalive: false,
    });
  }, SYNC_SOON_DEBOUNCE_MS);
}

function clearPracticeBatch(): void {
  clearTimeout(practiceTimer);
  practiceTimer = undefined;
  practiceAnswers = 0;
}

/**
 * Notes a practice answer (or an undo of one) written locally, and pushes
 * answers in batches: once `PRACTICE_BATCH_ANSWERS` have been given, or
 * `PRACTICE_BATCH_MS` after the first one waiting, whichever comes first.
 * The session's end (`practiceEnded`) and the page being hidden push the
 * rest. Nothing pulls here.
 */
export async function syncPractice(): Promise<void> {
  await useSync.getState().refreshQueue();
  practiceAnswers += 1;
  if (practiceAnswers >= PRACTICE_BATCH_ANSWERS) {
    void flushPractice();
    return;
  }
  practiceTimer ??= setTimeout(() => {
    void flushPractice();
  }, PRACTICE_BATCH_MS);
}

/** Pushes the practice answers waiting in this tab now. */
export function flushPractice(): Promise<void> {
  clearPracticeBatch();
  if (!platform.network.online) return Promise.resolve();
  return startOrJoin({ pull: 'never', freshMs: 0, hasChanges: true, force: false, keepalive: false });
}

/**
 * A session is starting: pull, unless a pull is fresh, so the cards are
 * the ones other devices left.
 */
export function practiceStarted(): Promise<void> {
  if (!platform.network.online) return Promise.resolve();
  return startOrJoin({
    pull: 'ifStale',
    freshMs: FRESH_PULL_MS,
    hasChanges: false,
    force: false,
    keepalive: false,
  });
}

/**
 * A session ended (its summary, or closed part way): push what is left of
 * its answers, and pull unless a pull is fresh.
 */
export function practiceEnded(): Promise<void> {
  clearPracticeBatch();
  if (!platform.network.online) return Promise.resolve();
  return startOrJoin({
    pull: 'ifStale',
    freshMs: FRESH_PULL_MS,
    hasChanges: true,
    force: false,
    keepalive: false,
  });
}

/** Forgets the loop's memory between tests: the backoff and the batch. */
export function __resetSyncForTests(): void {
  recovered();
  clearPracticeBatch();
  clearTimeout(soonTimer);
  soonTimer = undefined;
}
