/**
 * What the desktop app asks for when it opens /connect-desktop, read and
 * checked before anything is shown or minted.
 *
 * The desktop app signs in the way RFC 8252 asks of a native app: in the
 * system browser, with a loopback redirect and PKCE. It opens
 *
 *   /connect-desktop?redirect_uri=http://127.0.0.1:<port>/callback
 *                   &state=…&code_challenge=…&code_challenge_method=S256
 *
 * and listens on that port. When the learner allows it, this page asks the
 * API for a one-time code bound to the challenge and the address, and sends
 * the browser to the address with the code and the state. The code is
 * useless without the verifier, which never left the app.
 *
 * The address is the security boundary of this page: a code must only ever
 * go to the learner's own computer. So it is checked here, strictly, before
 * the page even offers to allow, and the API checks it again
 * (`domain/auth.CheckDesktopRedirect` in `lexpad_back`; keep the two in
 * step). Only `http://127.0.0.1:<port>/callback` and
 * `http://localhost:<port>/callback`, written exactly like that: a plain
 * port, that one path, no query, no fragment, no user name, no percent
 * signs. Anything else is refused without a redirect, because redirecting
 * somewhere we do not trust is the very thing to avoid.
 */

/** Where the desktop app listens. Mirrors the API's rule. */
const CALLBACK = /^http:\/\/(127\.0\.0\.1|localhost):([1-9][0-9]{0,4})\/callback$/;

/** An S256 challenge is the base64url of a SHA-256 digest: always 43 characters. */
const CHALLENGE = /^[A-Za-z0-9_-]{43}$/;

/**
 * The app's state is random and echoed back as it came. Generous bounds,
 * but only characters that need no escaping, so nothing odd is echoed.
 */
const STATE = /^[A-Za-z0-9._~-]{16,256}$/;

export interface DesktopRequest {
  redirectUri: string;
  state: string;
  codeChallenge: string;
}

/** Whether `raw` is exactly an address the desktop app could be listening on. */
export function isDesktopCallback(raw: string): boolean {
  const match = CALLBACK.exec(raw);
  if (match === null) return false;
  const port = Number(match[2]);
  return port >= 1 && port <= 65535;
}

/** The request in the page's address, or undefined when any part of it is not what the app sends. */
export function readDesktopRequest(params: URLSearchParams): DesktopRequest | undefined {
  const redirectUri = params.get('redirect_uri') ?? '';
  const state = params.get('state') ?? '';
  const codeChallenge = params.get('code_challenge') ?? '';
  const method = params.get('code_challenge_method') ?? '';
  if (!isDesktopCallback(redirectUri) || !STATE.test(state) || !CHALLENGE.test(codeChallenge))
    return undefined;
  // "plain" would put the verifier itself in this address.
  if (method !== 'S256') return undefined;
  return { redirectUri, state, codeChallenge };
}

/**
 * The address to send the browser to: the app's callback with the answer
 * and its state. Built from a request that passed `readDesktopRequest`, and
 * checked once more, so a mistake elsewhere cannot make it an open redirect.
 */
export function desktopCallbackUrl(
  request: DesktopRequest,
  answer: Record<string, string>,
): string | undefined {
  if (!isDesktopCallback(request.redirectUri)) return undefined;
  const query = new URLSearchParams({ ...answer, state: request.state });
  return `${request.redirectUri}?${query.toString()}`;
}
