import type { ApiAuthorizationRequest } from '@/api/types.js';
import { t } from '@/i18n/index.js';

/** The allow-listed family a connection's redirect belongs to, as the API verified it. */
export type KnownClient = NonNullable<ApiAuthorizationRequest['knownClient']>;

/**
 * What to call an assistant: its verified family, never the name it gave
 * itself. Anybody can register a client called "ChatGPT" from a port on
 * their own computer, so the self-declared name is only ever secondary
 * text. The two brand names are message strings (`connectAi.appChatgpt`,
 * `connectAi.appClaude`) because they are what the API's allow-list means.
 */
export function familyLabel(known: KnownClient | undefined): string {
  if (known === 'chatgpt') return t('connectAi.appChatgpt');
  if (known === 'claude') return t('connectAi.appClaude');
  if (known === 'local') return t('connectAi.appLocal');
  return t('connectAi.appUnknown');
}

/**
 * The self-declared name, when it says something the family label does not.
 * "ChatGPT" under "ChatGPT" is noise; "ChatGPT" under "An app on this
 * computer" is exactly what the learner should see.
 */
export function selfDeclared(clientName: string, known: KnownClient | undefined): string | undefined {
  const name = clientName.trim();
  if (name === '' || name.toLocaleLowerCase() === familyLabel(known).toLocaleLowerCase()) return undefined;
  return name;
}
